solution:
fn wrap[T](value: T) -> (T, Int) {
  return (value, 0);
}

fn main() -> Int {
  let inferred = wrap(42);           // T inferred as Int
  let explicit = wrap[Str]("hello"); // T explicit as Str
  return inferred.0;
}
